{
  "batch": 1,
  "condition": "relations_rule_only",
  "programs": [
    {
      "features": [],
      "name": "soft_closed_neighborhood",
      "rationale": "Uses a smooth count penalty that returns direct reward for isolates and approaches reward per conflict for large neighborhoods. Reach is local degree; scalar arithmetic is cheap, while active degree maintenance remains charged and blocker weights are ignored.",
      "rule": "weight / (1 + degree * (degree / (1 + degree)))"
    },
    {
      "features": [],
      "name": "effective_blocker_blend",
      "rationale": "Blends blocker count with conflict mass measured in units of the larger root or rival weight. Reach is the immediate weighted neighborhood; fixed arithmetic adds no traversal, but summary maintenance remains charged and neighbor compatibility is unknown.",
      "rule": "weight / (1 + 0.75 * degree + 0.25 * conflict_weight / (1 + max(weight, max_conflict_weight)))"
    },
    {
      "features": [],
      "name": "dominance_and_pressure",
      "rationale": "Softens the count penalty when root reward covers all blocker mass; otherwise uses the larger count or reward-relative mass pressure. Reach is one neighborhood, with fixed conditional arithmetic; aggregate maintenance remains charged and contested neighborhoods lack topology information.",
      "rule": "weight / (1 + 0.5 * degree) if weight >= conflict_weight else weight / (1 + max(degree, conflict_weight / (1 + weight)))"
    },
    {
      "features": [],
      "name": "bounded_density_discount",
      "rationale": "Modestly softens count pressure when the root blocks a large fraction of the active set, retaining a positive denominator throughout. Reach combines local degree and residual size; arithmetic is fixed, but active count updates remain charged and density does not reveal neighbor connectivity.",
      "rule": "weight / (1 + degree * (1 - 0.25 * min(1, degree / max(1, remaining_count - 1))))"
    },
    {
      "features": [],
      "name": "residual_mean_contrast",
      "rationale": "Adjusts count efficiency by a bounded comparison between mean preserved weight and mean blocker weight, keeping counts and weights separately normalized. Reach includes coarse residual totals; repeated scalar arithmetic and aggregate maintenance cost time, and preserved contacts may conflict with each other.",
      "rule": "weight / (1 + degree) * (1 + 0.15 * (compatible_weight / max(1, remaining_count - degree - 1) - conflict_weight / max(1, degree)) / (1 + compatible_weight / max(1, remaining_count - degree - 1) + conflict_weight / max(1, degree)))"
    },
    {
      "features": [],
      "name": "bounded_rival_adjustment",
      "rationale": "Applies a bounded strongest-rival margin correction to reward per blocked count, preserving reward units and positive scores. Reach is local degree and maximum rival weight; arithmetic is fixed, while summary refresh remains charged and several feasible rivals can defeat the exchange proxy.",
      "rule": "weight / (1 + degree) * (1 + 0.2 * (weight - max_conflict_weight) / (1 + weight + max_conflict_weight))"
    },
    {
      "features": [],
      "name": "reward_with_soft_occupancy",
      "rationale": "Retains reward scale with a modest bounded penalty for resource gap overhead relative to contact duration. Reach is root-only with few scalar operations; common-kernel work still applies, and the occupancy proxy ignores graph displacement.",
      "rule": "weight * (1 - 0.15 * max(station_gap, satellite_gap) / (1 + duration + max(station_gap, satellite_gap)))"
    },
    {
      "features": [],
      "name": "capped_capture_envelope",
      "rationale": "Takes the larger count-efficiency or weighted-capture estimate, capped at twenty percent above count efficiency. Reach is local count and conflict mass; min/max arithmetic is fixed and summary maintenance remains charged, while optimistic capture can overvalue overlapping alternatives.",
      "rule": "min(1.2 * weight / (1 + degree), max(weight / (1 + degree), weight * (weight / (1 + weight + conflict_weight))))"
    }
  ],
  "round": 2
}
